    @font-face { font-family:'Inter'; font-style:normal; font-weight:900; font-display:swap; src:url('/font/Inter-900.woff2') format('woff2'); }

    @font-face { font-family:'Inter'; font-style:italic; font-weight:100; font-display:swap; src:url('/font/Inter-100italic.woff2') format('woff2'); }
    @font-face { font-family:'Inter'; font-style:italic; font-weight:200; font-display:swap; src:url('/font/Inter-200italic.woff2') format('woff2'); }
    @font-face { font-family:'Inter'; font-style:italic; font-weight:300; font-display:swap; src:url('/font/Inter-300italic.woff2') format('woff2'); }
    @font-face { font-family:'Inter'; font-style:italic; font-weight:400; font-display:swap; src:url('/font/Inter-italic.woff2') format('woff2'); }
    @font-face { font-family:'Inter'; font-style:italic; font-weight:500; font-display:swap; src:url('/font/Inter-500italic.woff2') format('woff2'); }
    @font-face { font-family:'Inter'; font-style:italic; font-weight:600; font-display:swap; src:url('/font/Inter-600italic.woff2') format('woff2'); }
